<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard | AppTasker</title><style>:root{--n:#101828;--b:#526df5;--bg:#f5f7fb;--m:#667085;--l:#e7eaf0}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,system-ui;color:var(--n)}.side{position:fixed;width:250px;inset:0 auto 0 0;background:#101828;color:#fff;padding:25px 18px}.brand{font-size:23px;font-weight:900;margin:5px 10px 28px}.side a{display:block;color:#bdc5d5;text-decoration:none;padding:13px;border-radius:11px}.side a.active,.side a:hover{background:#ffffff12;color:#fff}.main{margin-left:250px;padding:30px}.top{display:flex;justify-content:space-between;align-items:center}.logout{padding:10px 14px;border:1px solid var(--l);border-radius:10px;background:white}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.stat,.panel{background:#fff;border:1px solid var(--l);border-radius:18px;padding:19px}.stat small{color:var(--m)}.stat strong{display:block;font-size:29px;margin-top:7px}.grid{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.row{padding:14px 0;border-bottom:1px solid #eee;display:flex;justify-content:space-between;gap:12px}.row:last-child{border:0}.muted{color:var(--m);font-size:12px}.pill{font-size:11px;font-weight:800;background:#fff7e8;color:#9a5b00;padding:5px 8px;border-radius:99px}.link{color:var(--b);font-weight:800;text-decoration:none}@media(max-width:850px){.side{position:static;width:auto}.side a{display:inline-block}.main{margin:0;padding:18px}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}}@media(max-width:480px){.stats{grid-template-columns:1fr 1fr}.side{padding:16px}.brand{margin-bottom:12px}}</style></head><body><aside class="side"><div class="brand">A · AppTasker Admin</div><a class="active" href="{{ route('admin.dashboard') }}">Dashboard</a><a href="{{ route('admin.submissions') }}">Submissions</a><a href="#">Tasks</a><a href="#">Workers</a><a href="#">Clients</a></aside><main class="main"><header class="top"><div><small>ADMIN WORKSPACE</small><h1>Control Center</h1></div><form method="POST" action="{{ route('logout') }}">@csrf<button class="logout">Logout</button></form></header><section class="stats"><div class="stat"><small>Workers</small><strong>{{ $stats['workers'] }}</strong></div><div class="stat"><small>Clients</small><strong>{{ $stats['clients'] }}</strong></div><div class="stat"><small>Tasks</small><strong>{{ $stats['tasks'] }}</strong></div><div class="stat"><small>Pending Review</small><strong>{{ $stats['pending'] }}</strong></div></section><section class="grid"><div class="panel"><h2>Recent submissions</h2>@forelse($submissions as $s)<div class="row"><div><strong>{{ $s->workerTask->task->title }}</strong><div class="muted">{{ $s->workerTask->user->name }} · {{ $s->original_name }}</div></div><span class="pill">{{ ucfirst($s->status) }}</span></div>@empty<p class="muted">No submissions yet.</p>@endforelse<a class="link" href="{{ route('admin.submissions') }}">Review all submissions →</a></div><div class="panel"><h2>Latest tasks</h2>@foreach($tasks as $task)<div class="row"><div><strong>{{ $task->title }}</strong><div class="muted">{{ strtoupper($task->type) }} · {{ ucfirst($task->slot) }}</div></div><strong>${{ number_format((float)$task->reward,2) }}</strong></div>@endforeach</div></section></main></body></html>